// 每个新静态终态凭据与原Task和Common事实双向闭合；当前空库存不能补旧历史缺口。
#include "task_static_asset.hpp"
#include <charconv>
#include <limits>
#include <set>
namespace hanmo::resident { namespace {
// 所有实例ID保原统一分配序；错误前缀、前导零与未来号都拒绝。
std::optional<Integer> sequence(const StableId& id,const StableId& prefix,Integer next){const auto head=prefix+":";if(id.compare(0,head.size(),head)!=0)return {};const auto tail=id.substr(head.size());Integer value=0;const auto parsed=std::from_chars(tail.data(),tail.data()+tail.size(),value);if(tail.empty()||parsed.ec!=std::errc{}||parsed.ptr!=tail.data()+tail.size()||value<=0||value>=next||std::to_string(value)!=tail)return {};return value;}
bool owner_is(const Owner& owner,Owner::Kind kind,const StableId& id){return !owner.extra&&owner.kind==kind&&owner.id==id;}
}
Status validate_task_static_assets(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskStaticAssetState& state,const DynamicStepInput* phase){
    if(state.version!=1)return common_failure("UnsupportedTaskStaticAssetVersion");Integer observed=common.tick();if(phase){if(phase->from_tick!=common.tick()||phase->from_tick<0||phase->from_tick==std::numeric_limits<Integer>::max()||phase->to_tick!=phase->from_tick+1)return common_failure("TaskStaticAssetPhaseMismatch");observed=phase->to_tick;}
    CheckpointMap<StableId,std::vector<StableId>> observed_by;std::set<StableId> covered,actions,destinations;Integer previous_fact=0;const auto& fact_order=common.state().facts.order();std::size_t previous_position=0;bool first=true;
    for(const auto& row:state.receipts.rows()){
        const auto& receipt=row.second;const auto* head=common.state().facts.find(row.first);const auto* task=tasks.tasks.find(receipt.task_id);const auto* definition=task?catalog.offers.find(task->offer_id):nullptr;const auto* actor=task?common.actor(task->assignee):nullptr;const auto fact=sequence(row.first,task_static_asset_fact_kind,common.state().next_instance_id);const auto serial=task?sequence(task->id,"task",common.state().next_instance_id):std::nullopt;const auto settlement=task?sequence(task->settlement_id,"settlement",common.state().next_instance_id):std::nullopt;
        const auto position=std::find(fact_order.begin(),fact_order.end(),row.first);const auto offset=static_cast<std::size_t>(position-fact_order.begin());
        if(row.first!=receipt.fact_id||!head||head->id!=row.first||head->kind!=task_static_asset_fact_kind||head->domain!="tasks"||!task||task->contract_id||!definition||!actor||!fact||!serial||!settlement||*serial>=*fact||*fact>=*settlement||*fact<=previous_fact||position==fact_order.end()||(!first&&offset<=previous_position)||!covered.insert(task->id).second||receipt.offer_id!=task->offer_id||receipt.assignee_actor_id!=task->assignee||receipt.original_issuer.extra||!owner_equal(receipt.original_issuer,definition->issuer)||receipt.tick<task->accepted_tick||receipt.tick>observed||receipt.tick<0)return common_failure("InvalidTaskStaticAssetSource",row.first);
        first=false;previous_position=offset;previous_fact=*fact;observed_by[receipt.assignee_actor_id].push_back(row.first);
        const auto* issuer=definition->issuer.kind==Owner::Kind::actor?common.actor(definition->issuer.id):nullptr;const auto destination=issuer?issuer->inventory_id:"store:"+definition->issuer.id;
        if((definition->issuer.kind!=Owner::Kind::actor&&definition->issuer.kind!=Owner::Kind::organization)||(definition->issuer.kind==Owner::Kind::actor&&!issuer)||receipt.from_inventory_id!=actor->inventory_id||receipt.to_inventory_id!=destination||destination==receipt.from_inventory_id||!common.inventory(destination)||!common.inventory(receipt.from_inventory_id)||!owner_is(receipt.from_container_owner,Owner::Kind::actor,task->assignee)||receipt.to_container_owner.extra||receipt.to_container_owner.id.empty()||!owner_equal(receipt.to_container_owner,definition->issuer))return common_failure("InvalidTaskStaticAssetContainers",row.first);
        const bool delivery=receipt.stage=="procurement_delivery";
        if(delivery){auto action=sequence(receipt.source_action_id,"action",common.state().next_instance_id);if(definition->template_id!="procurement"||definition->goal.quantity<=0||task->status!="success"||task->reported_tick!=receipt.tick||!action||*action<=*serial||*action>=*fact||!actions.insert(receipt.source_action_id).second)return common_failure("InvalidTaskStaticAssetDelivery",row.first);}
        else if(receipt.stage!="cancellation_return"||!receipt.source_action_id.empty()||task->reported_tick||task->status!=(receipt.tick>task->deadline_tick?"failed":"cancelled")||(definition->template_id!="procurement"&&definition->template_id!="message"&&definition->template_id!="escort"))return common_failure("InvalidTaskStaticAssetCancellation",row.first);
        Integer total=0,last_destination=0;bool reached_private=false;std::set<StableId> sources;
        for(const auto& leg:receipt.legs){auto source=sequence(leg.source_lot_id,"lot",common.state().next_instance_id),to=sequence(leg.destination_lot_id,"lot",common.state().next_instance_id);const bool task_owned=owner_is(leg.source_owner,Owner::Kind::task,task->id);const bool private_owned=owner_is(leg.source_owner,Owner::Kind::actor,task->assignee);
            if(!shared.items.find(leg.item_id)||!source||!to||*source>=*to||*to>=*fact||*to<=last_destination||!sources.insert(leg.source_lot_id).second||!destinations.insert(leg.destination_lot_id).second||leg.quantity<=0||leg.source_quantity_before<leg.quantity||leg.source_quantity_after!=0||leg.source_quantity_before!=leg.quantity||leg.destination_owner.extra||!owner_equal(leg.destination_owner,definition->issuer)||leg.source_owner.extra||(!task_owned&&!private_owned)||(task_owned&&*source<=*serial)||leg.reservation!=(delivery?ReservationRef{receipt.source_action_id}:ReservationRef{}))return common_failure("InvalidTaskStaticAssetLeg",row.first);
            last_destination=*to;if(delivery){if(leg.item_id!=definition->goal.item_id||(task_owned&&reached_private)||leg.quantity>definition->goal.quantity-total)return common_failure("TaskStaticAssetQuantityMismatch",row.first);total+=leg.quantity;if(private_owned)reached_private=true;}else if(!task_owned||leg.source_quantity_after!=0)return common_failure("TaskStaticAssetReturnOwnership",row.first);
        }
        if(delivery&&total!=definition->goal.quantity)return common_failure("TaskStaticAssetQuantityMismatch",row.first);
        std::set<StableId> retained;for(const auto& remaining:receipt.retained_task_goods){auto lot=sequence(remaining.lot_id,"lot",common.state().next_instance_id);if(!lot||*lot<=*serial||*lot>=*fact||!common.inventory(remaining.inventory_id)||!shared.items.find(remaining.item_id)||remaining.quantity<=0||!retained.insert(remaining.lot_id).second||destinations.count(remaining.lot_id))return common_failure("InvalidTaskStaticAssetRemainder",row.first);for(const auto& leg:receipt.legs)if(leg.source_lot_id==remaining.lot_id&&(!owner_is(leg.source_owner,Owner::Kind::task,task->id)||remaining.inventory_id!=receipt.from_inventory_id||remaining.item_id!=leg.item_id||remaining.quantity!=leg.source_quantity_after))return common_failure("TaskStaticAssetRemainderMismatch",row.first);if(!delivery&&remaining.inventory_id==receipt.from_inventory_id&&remaining.reservation==ReservationRef{})return common_failure("TaskStaticAssetReturnIncomplete",row.first);}
    }
    for(const auto& row:common.state().facts.rows())if(row.second.kind==task_static_asset_fact_kind&&(row.second.domain!="tasks"||!state.receipts.find(row.first)))return common_failure("MissingTaskStaticAssetReceipt",row.first);
    for(const auto& row:tasks.tasks.rows()){const auto& task=row.second;const auto* d=catalog.offers.find(task.offer_id);if(task.contract_id||!d)continue;const bool relevant=!task.settlement_id.empty()&&((d->template_id=="procurement"&&task.status=="success")||((d->template_id=="procurement"||d->template_id=="message"||d->template_id=="escort")&&!task.reported_tick&&(task.status=="cancelled"||task.status=="failed")));if(relevant!=(covered.count(task.id)!=0))return common_failure("TaskStaticAssetCoverageMismatch",task.id);}
    if(observed_by!=state.observed_by)return common_failure("TaskStaticAssetObserverIndexMismatch");return common_success();
}
Status validate_task_static_asset_layout(const CommonStore& common,bool enabled,const std::vector<std::pair<StableId,StableId>>& modules,const TaskStaticAssetState* state){Integer count=0;for(const auto& row:modules)if(row.first=="task_static_assets"){++count;if(row.second!="1")return common_failure("UnsupportedTaskStaticAssetVersion");}if(count!=(enabled?1:0)||enabled!=(state!=nullptr)||(state&&state->version!=1))return common_failure("TaskStaticAssetProfileMismatch");if(!enabled)for(const auto& row:common.state().facts.rows())if(row.second.kind==task_static_asset_fact_kind)return common_failure("TaskStaticAssetProfileRequired",row.first);return common_success();}
Outcome<bool> decode_task_static_asset_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{boundary::object(scenario,"scenario");const auto* profile=scenario.find("task_static_asset_profile");if(!profile)return {true,false,{}};if(boundary::string(*profile,"scenario/task_static_asset_profile")!="original_task_assets_v1")boundary::unsupported("UnsupportedTaskStaticAssetProfile","scenario/task_static_asset_profile");for(const auto* cap:{"task_static_assets_v1","native_dynamic_world","multi_actor"})if(std::find(capabilities.begin(),capabilities.end(),cap)==capabilities.end())boundary::unsupported("MissingTaskStaticAssetCapability",cap);const auto* dynamic=scenario.find("dynamic_world");const auto* native=dynamic?dynamic->find("profile"):nullptr;if(!native||boundary::string(*native,"scenario/dynamic_world/profile")!="local_society_v1")boundary::unsupported("TaskStaticAssetNativeProfileRequired","scenario/dynamic_world/profile");return {true,true,{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
}
